def transform_simple(grid):
    if not grid:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    # Find base row
    base_row = -1
    base_val = 0
    for r in range(rows):
        val = grid[r][0]
        if val != 0 and all(grid[r][c] == val for c in range(cols)):
            base_row = r
            base_val = val
            break

    # Identify background value
    bg_val = 0
    if grid:
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] != base_val:
                    bg_val = grid[r][c]
                    break

    output = [[0] * cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]

            if val == bg_val:
                output[r][c] = val
            elif val == base_val and r == base_row:
                output[r][c] = 2
            elif val == base_val:
                v_count = 0
                if r > 0 and grid[r-1][c] == val:
                    v_count += 1
                if r < rows - 1 and grid[r+1][c] == val:
                    v_count += 1
                if v_count == 0:
                    output[r][c] = val
                else:
                    output[r][c] = 2
            else:
                output[r][c] = val

    return output

